// Base64 encoding/decoding for environments without btoa/atob
function base64Encode(bytes: Uint8Array): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let result = '';
  let i = 0;
  while (i < bytes.length) {
    const b1 = bytes[i++];
    const b2 = i < bytes.length ? bytes[i++] : 0;
    const b3 = i < bytes.length ? bytes[i++] : 0;
    const triple = (b1 << 16) | (b2 << 8) | b3;
    result += chars[(triple >> 18) & 0x3F];
    result += chars[(triple >> 12) & 0x3F];
    result += i > bytes.length + 1 ? '=' : chars[(triple >> 6) & 0x3F];
    result += i > bytes.length ? '=' : chars[triple & 0x3F];
  }
  return result;
}

function base64Decode(str: string): Uint8Array {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup: Record<string, number> = {};
  for (let i = 0; i < chars.length; i++) {
    lookup[chars[i]] = i;
  }
  str = str.replace(/=/g, '');
  const bytes = new Uint8Array((str.length * 3) / 4);
  let j = 0;
  for (let i = 0; i < str.length; i += 4) {
    const c1 = lookup[str[i]];
    const c2 = lookup[str[i + 1]];
    const c3 = lookup[str[i + 2]] ?? 0;
    const c4 = lookup[str[i + 3]] ?? 0;
    const triple = (c1 << 18) | (c2 << 12) | (c3 << 6) | c4;
    bytes[j++] = (triple >> 16) & 0xFF;
    if (i + 2 < str.length) bytes[j++] = (triple >> 8) & 0xFF;
    if (i + 3 < str.length) bytes[j++] = triple & 0xFF;
  }
  return bytes.slice(0, j);
}

// Web Crypto API types
declare global {
  interface Crypto {
    subtle: {
      importKey: (format: string, keyData: BufferSource, algorithm: AlgorithmIdentifier, extractable: boolean, keyUsages: KeyUsage[]) => Promise<CryptoKey>;
      sign: (algorithm: string, key: CryptoKey, data: BufferSource) => Promise<ArrayBuffer>;
    };
  }
  var crypto: Crypto;
}

export interface ConnectorConfig {
  shopifyClientSecret: string;
  slackBotToken: string;
  slackChannel: string;
  rawBody?: string;
  hmacSignature?: string;
  fetch?: typeof fetch;
}

export interface ShopifyOrderPayload {
  id: number;
  name: string;
  email: string;
  total_price: string;
  line_items: Array<{
    title: string;
    quantity: number;
    price: string;
  }>;
}

export interface HandleResult {
  slackMessageTs: string;
  slackChannel: string;
}

async function verifyHmac(rawBody: string, signatureB64: string, secret: string): Promise<void> {
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(rawBody);

  const key = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );

  const signatureBuffer = await crypto.subtle.sign('HMAC', key, messageData);
  const expectedSignatureB64 = base64Encode(new Uint8Array(signatureBuffer));

  // Constant-time comparison
  const actualBytes = base64Decode(signatureB64);
  const expectedBytes = base64Decode(expectedSignatureB64);

  if (actualBytes.length !== expectedBytes.length) {
    throw new Error('Invalid HMAC signature');
  }

  let diff = 0;
  for (let i = 0; i < actualBytes.length; i++) {
    diff |= actualBytes[i] ^ expectedBytes[i];
  }

  if (diff !== 0) {
    throw new Error('Invalid HMAC signature');
  }
}

export async function handle(
  payload: ShopifyOrderPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (payload.id === undefined || payload.id === null) {
    throw new Error('Missing required field: id');
  }
  if (!payload.name) {
    throw new Error('Missing required field: name');
  }
  if (!payload.email) {
    throw new Error('Missing required field: email');
  }
  if (!payload.total_price) {
    throw new Error('Missing required field: total_price');
  }
  if (!payload.line_items || !Array.isArray(payload.line_items)) {
    throw new Error('Missing required field: line_items');
  }

  // Verify HMAC if raw body and signature provided
  if (config.rawBody && config.hmacSignature) {
    await verifyHmac(config.rawBody, config.hmacSignature, config.shopifyClientSecret);
  }

  // Format line items summary
  const lineItemsSummary = payload.line_items
    .map(item => `${item.quantity}x ${item.title}`)
    .join(', ');

  // Format Slack message text
  const text = `New order ${payload.name} from ${payload.email}: $${payload.total_price} - ${lineItemsSummary}`;

  // Send to Slack
  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text: text,
    }),
  });

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`);
  }

  const result = await response.json() as { ok: boolean; channel: string; ts: string };

  if (!result.ok) {
    throw new Error(`Slack API returned error: ${JSON.stringify(result)}`);
  }

  return {
    slackMessageTs: result.ts,
    slackChannel: result.channel,
  };
}

