async function verifyHmac(rawBody: string, signatureB64: string, secret: string): Promise<void> {
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(rawBody);

  // Use the Web Crypto API's subtle interface (available in Cloudflare Workers, etc.)
  const subtle = (globalThis.crypto as unknown as { subtle: { importKey: Function; sign: Function } }).subtle;

  const key = await subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );

  const signatureBuffer = await subtle.sign('HMAC', key, messageData);
  const expectedSignatureB64 = base64Encode(new Uint8Array(signatureBuffer));

  // Constant-time comparison
  const actualBytes = base64Decode(signatureB64);
  const expectedBytes = base64Decode(expectedSignatureB64);

  if (actualBytes.length !== expectedBytes.length) {
    throw new Error('Invalid HMAC signature');
  }

  let diff = 0;
  for (let i = 0; i < actualBytes.length; i++) {
    diff |= actualBytes[i] ^ expectedBytes[i];
  }

  if (diff !== 0) {
    throw new Error('Invalid HMAC signature');
  }
}

export async function handle(
  payload: ShopifyOrderPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (payload.id === undefined || payload.id === null) {
    throw new Error('Missing required field: id');
  }
  if (!payload.name) {
    throw new Error('Missing required field: name');
  }
  if (!payload.email) {
    throw new Error('Missing required field: email');
  }
  if (!payload.total_price) {
    throw new Error('Missing required field: total_price');
  }
  if (!payload.line_items || !Array.isArray(payload.line_items)) {
    throw new Error('Missing required field: line_items');
  }

  // Verify HMAC if raw body and signature provided
  if (config.rawBody && config.hmacSignature) {
    await verifyHmac(config.rawBody, config.hmacSignature, config.shopifyClientSecret);
  }

  // Format line items summary
  const lineItemsSummary = payload.line_items
    .map(item => `${item.quantity}x ${item.title}`)
    .join(', ');

  // Format Slack message text
  const text = `New order ${payload.name} from ${payload.email}: $${payload.total_price} - ${lineItemsSummary}`;

  // Send to Slack
  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text: text,
    }),
  });

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`);
  }

  const result = await response.json() as { ok: boolean; channel: string; ts: string };

  if (!result.ok) {
    throw new Error(`Slack API returned error: ${JSON.stringify(result)}`);
  }

  return {
    slackMessageTs: result.ts,
    slackChannel: result.channel,
  };
}

